contract Adversary {
    bool public doRevert;
    constructor(bool _doRevert) payable {
        doRevert = _doRevert;
    }
    // fallback/receive: if configured, revert to make send/transfer behave differently
    receive() external payable {
        if (doRevert) revert("bad");
    }
    fallback() external payable {
        if (doRevert) revert("bad");
    }
}

