        // the attacker must be msg.sender when calling withdraw. So we have attacker call c.withdraw(amount).

        // Fund attacker so it can perform any operations
        vm.deal(address(attacker), 1 ether);

        // Make attacker call c.withdraw(amount)
        try attacker.doWithdraw{gas: gasleft()}(c, amount) {
            ok = true;
        } catch {
