    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // keep value within reasonable bounds so vm.deal can fund actors
        value = bound(value, 0, 1 ether);

        // deploy an adversarial counterparty that always reverts on receive/call
        Reverter r = new Reverter();

        // ensure the target is the reverter's address when fuzzed target equals zero or non-contract
        address chosen = target;
        // If fuzzer passed an address equal to the deployed reverter, use it; otherwise prefer the reverter to trigger the adversarial behaviour
        // but still allow other addresses: choose reverter when chosen is not a contract
        uint256 codeSize;
        assembly { codeSize := extcodesize(chosen) }
        if (codeSize == 0) chosen = address(r);

        // fund the contract so it can send value
        vm.deal(address(c), value);

        // Owner is the deployer (this test contract). Ensure msg.sender is owner when calling.
        bool ok;
        try c.sendMoney{value: 0}(chosen, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: when the callee reverts on low-level call, the reference contract's sendMoney must revert (ok == false).
        // The mutant that transfers to msg.sender would NOT revert for such inputs, so the property distinguishes them.
        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("nope");
    }
    receive() external payable {
        revert("nope");
    }
}

