pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to send and an arbitrary bytes data
    function testFuzz_property(uint256 value, bytes calldata data) public {
        // keep value reasonable so vm.deal and transfers work within address space
        value = bound(value, 0, 1 ether);

        // deploy a helper that ACCEPTS funds (so correct contract's low-level call should succeed)
        Accepting recipient = new Accepting();

        // fund the contract so it can send
        vm.deal(address(c), 1 ether);

        uint256 before = address(recipient).balance;

        // owner is the test contract because c was created in setUp by this address
        // call sendMoney as owner (no prank needed)
        bool ok;
        try c.sendMoney(address(recipient), value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(recipient).balance;

        // General rule: for the correct contract, when the recipient accepts funds, calling sendMoney
        // increases the recipient's balance by exactly value (ok must be true and after - before == value).
        // The mutant that transfers to msg.sender will not increase recipient's balance for some inputs.
        assertTrue(ok && (after - before == value));
    }
}

// helper that simply accepts funds
contract Accepting {
    receive() external payable {}
    fallback() external payable {}
}

