pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        // keep domain wide but sensible: value fits in contract balance we will set
        vm.assume(target != address(0));
        // fund the contract so it has enough balance to send
        uint256 startBal = 1 ether + (value % 1 ether); // ensure >= value for wide domain
        vm.deal(address(c), startBal);

        // record balance before
        uint256 before = address(c).balance;

        // call as owner (deployer is owner by constructor)
        // owner is this test contract by default; make the call directly
        try c.sendMoney(target, value, data) {
            // success
        } catch {
            // ignore reverts: the property we assert is about balance decrease when call completes
        }

        // exactly one assertion: after a completed sendMoney call, the contract's balance is reduced by value
        // We assert the general property: address(c).balance == before - value OR if call reverted then balance unchanged.
        // But to make a single clear universal property that the correct contract always satisfies for ALL inputs
        // and the mutant fails for some, we assert that if the call did NOT revert then balance == before - value.
        bool ok;
        // detect whether the call would have reverted by trying again in a try/catch and observing revert
        try c.sendMoney(target, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == before - value);
        } else {
            // if it reverted, the reference also reverts for inputs where low-level call fails; in that case
            // the property about balance decrease does not apply, so assertTrue on a tautology referencing c: owner remains owner
            // use public getter owner to observe c (owner is public in C)
            // single assertion required overall, so we map both branches to one assertTrue by making a condition that
            // is true for reference for all inputs: either call succeeded and balance decreased by value, or owner unchanged
            assertTrue(c.owner() == payable(address(this)));
        }
    }
}

