pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: target address (to call), value to send, arbitrary calldata
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // admissible domain: value should be small enough to fund from this test account
        // and not overflow native operations; keep wide but bounded.
        value = bound(value, 0, 1 ether);

        // must be owner to call sendMoney; set test contract as owner (c initialized with this contract as deployer)
        // fund the contract so it can send value
        vm.deal(address(c), 1 ether);

        // record owner's balance (owner == address(this) in this test)
        uint256 beforeOwnerBalance = address(this).balance;

        // call sendMoney as owner and catch any revert; we don't assert on revert here — only on final owner balance
        bool ok;
        try c.sendMoney(target, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference contract, the owner (msg.sender) should not receive funds from sendMoney —
        // i.e., owner's balance must remain exactly the same regardless of target/data/value (for all admissible inputs).
        // The mutant that redirects funds to msg.sender will make owner's balance increase for some inputs,
        // causing this assertion to fail.
        assertTrue(address(this).balance == beforeOwnerBalance);
    }
}
